'use client';

import React, { useState } from 'react';
import Image from 'next/image';

const BusinessDashboard: React.FC = () => {
    const [activeTab, setActiveTab] = useState('project');

    const tabs = [
        { id: 'project', label: 'Project Management' },
        { id: 'team', label: 'Team Collaboration' },
        { id: 'analytics', label: 'Advanced Analytics' },
        { id: 'crm', label: 'CRM & Customer Support' }
    ];

    return (
        <div className="min-h-screen font-display bg-white">
            {/* Hero section */}
            <div className="relative">
                <div className="pt-16 pb-45 z-10 relative max-w-5xl mx-auto px-4 text-center">
                    {/* Header */}
                    <div className="text-center mb-12">
                        <div className="inline-block mb-4 px-4 py-1.5 bg-white/60 backdrop-blur-sm rounded-full border border-gray-200/50 shadow-sm">
                            <span className="text-xs font-medium text-gray-600 tracking-wide">NEXT ESSENTIAL</span>
                        </div>
                        <h1 className="font-display text-5xl md:text-6xl font-bold text-gray-800 mb-2 leading-tight">
                            Everything You Need to Run and<br />Scale Your Business
                        </h1>
                    </div>

                    {/* Tabs */}
                    <div className="flex flex-wrap gap-2 mb-8 justify-center">
                        {tabs.map((tab) => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`px-6 py-2.5 text-sm font-medium transition-all duration-300 ${
                                    activeTab === tab.id
                                        ? ' text-blue-500'
                                        : 'bg-white/40 text-gray-600'
                                }`}
                            >
                                {tab.label}
                            </button>
                        ))}
                    </div>
                </div>
                
                {/* Soft blurred transition overlay */}
                {/* <div className="absolute bottom-0 left-0 w-full h-64 bg-gradient-to-r from-purple-200 via-pink-300 to-purple-200/20 blur-2xl opacity-80" /> */}
            </div>
            
            {/* Dashboard section */}
            <div className="relative -mt-32 lg:-mt-48 z-10 max-w-6xl mx-auto px-16 pb-8">
                <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-200/50">
                    {/* Decorative Elements */}
                    <div className="absolute top-0 left-0 w-full h-full opacity-30 pointer-events-none">
                        <div className="absolute top-10 right-20 w-32 h-32 bg-purple-400/20 rounded-full blur-3xl"></div>
                        <div className="absolute bottom-20 left-10 w-40 h-40 bg-pink-400/20 rounded-full blur-3xl"></div>
                    </div>

                    <div className="relative p-12 grid md:grid-cols-2 gap-12 items-center">
                        {/* Left Section - Image */}
                        <div className="relative w-full h-full min-h-[400px]">
                            <Image
                                src="/vercel.svg"
                                alt="Team Collaboration"
                                fill
                                className="object-cover rounded-2xl"
                                priority
                            />
                        </div>
                        <div className="relative w-full h-full min-h-[400px]">
                            <Image
                                src="/vercel.svg"
                                alt="Team Collaboration"
                                fill
                                className="object-cover rounded-2xl"
                                priority
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default BusinessDashboard;